function m(){document.addEventListener("alpine:init",()=>{window.Alpine.data("hamtaProductCard",(i={})=>({productId:i.productId||0,image:i.image||"",permalink:i.permalink||"",colors:Array.isArray(i.colors)?i.colors:[],selectedColor:"",wishlisted:!1,timer:{visible:!1,label:"00:00:00:00"},_timerId:null,init(){this.loadWishlist(),i.timerEnd&&i.timerEnd>Math.floor(Date.now()/1e3)&&this.startTimer(i.timerEnd)},destroy(){this._timerId&&clearInterval(this._timerId)},loadWishlist(){try{const t=JSON.parse(localStorage.getItem("hamta_wishlist")||"[]");this.wishlisted=t.map(String).includes(String(this.productId))}catch{this.wishlisted=!1}},toggleWishlist(){let t=[];try{t=JSON.parse(localStorage.getItem("hamta_wishlist")||"[]")}catch{t=[]}const s=String(this.productId);t.map(String).includes(s)?(t=t.filter(r=>String(r)!==s),this.wishlisted=!1):(t.push(this.productId),this.wishlisted=!0),localStorage.setItem("hamta_wishlist",JSON.stringify(t))},selectColor(t){this.selectedColor=t.slug,t.image&&(this.image=t.image),t.permalink&&(this.permalink=t.permalink)},startTimer(t){const s=()=>{const r=Math.floor(Date.now()/1e3);let e=t-r;if(e<=0){this.timer.visible=!1,this.timer.label="00:00:00:00",this._timerId&&clearInterval(this._timerId);return}this.timer.visible=!0;const a=Math.floor(e/86400);e%=86400;const h=Math.floor(e/3600);e%=3600;const d=Math.floor(e/60),n=e%60,l=o=>String(o).padStart(2,"0");this.timer.label=`${l(a)}:${l(h)}:${l(d)}:${l(n)}`};s(),this._timerId=setInterval(s,1e3)}}))})}m();
